from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import NoSuchElementException
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage


class CentralizedRetManagementPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Configuration', 'Centralized RET Management']

    def __init__(self, driver):
        super(CentralizedRetManagementPage, self).__init__(driver)
        self._view_panel = CentralizedRetManagementPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_ret_info_from_ret_management(self, ald=None, timeout=60):
        return self._view_panel.get_ret_info_from_ret_management(ald, timeout)

    def calibrate_ret_from_ret_management(self, ald, timeout=60):
        self._view_panel.calibrate_ret_from_ret_management(ald, timeout)


class CentralizedRetManagementPageViewPanel(ViewPanel):
    _HEAD_TITLE = '//*[@class="ret-management-body"]//thead//tr[1]//span[@title]'
    _RET_BODY_TR = '//*[@class="ret-management-body"]//tbody//tr'
    _TR_BY_ALD_NAME = _RET_BODY_TR + '[//*[@title="{}"]]//td/div[not(@ng-reflect-ng-switch="icon")]'
    _CALIBRATE = _RET_BODY_TR + '[//*[@title="{}"]]//td[div[@*="calibrate"]]'
    _CALIBRATE_INPUT = _CALIBRATE + "//input"
    _CALIBRATE_CHECK_BOX = _CALIBRATE + '//*[contains(@class, "p-checkbox-box")]'
    _SEND = '//*[@class="ret-send-button"]//button'

    def __init__(self, driver):
        super(CentralizedRetManagementPageViewPanel, self).__init__(driver)

    def get_ret_info_from_ret_management(self, ald=None, timeout=60):
        self.wait_for_visibility_by_xpath(self._HEAD_TITLE, timeout)
        titles = [title.split('[')[0].strip() for title in self.get_fields_info_from_row(self._HEAD_TITLE, timeout)]
        ald_info = []

        if ald:
            elems = self.driver.find_elements_by_xpath(self._TR_BY_ALD_NAME.format(ald))
            status = self._get_info_from_tr(elems)
            ald_info.append(dict(zip(titles, status)))
        else:
            for elem_tr in self.driver.find_elements_by_xpath(self._RET_BODY_TR):
                elems = elem_tr.find_elements_by_xpath('.//td/div[not(@ng-reflect-ng-switch="icon")]')
                status = self._get_info_from_tr(elems)
                ald_info.append(dict(zip(titles, status)))
        return ald_info

    def _get_info_from_tr(self, elems):
        #
        status = []
        for elem in elems:
            if elem.get_attribute('ng-reflect-ng-switch') == "actionState":
                info = elem.text.strip()
                if not info and "mdi" in elem.find_element_by_xpath('.//i').get_attribute('class'):
                    status.append('success')
                else:
                    status.append(info)
                continue

            if elem.get_attribute('ng-reflect-ng-switch') == "calibrate":
                info = elem.find_element_by_xpath('.//p-checkbox').get_attribute("ng-reflect-model")
                status.append(info)
                continue

            try:
                info = elem.find_element_by_xpath('.//input[@type="text"]').get_attribute("ng-reflect-model")
            except NoSuchElementException:
                info = elem.text.strip()
            status.append(info)
        return status

    def calibrate_ret_from_ret_management(self, ald, timeout=60):
        self.select_checkbox_by_specified_status(True,
                                                 self._CALIBRATE_INPUT.format(ald),
                                                 self._CALIBRATE_CHECK_BOX.format(ald))
        self.click_enabled_element((By.XPATH, self._SEND), timeout)
